CREATE TABLE hr_employees(id text PRIMARY KEY,employee_no text UNIQUE NOT NULL,name text NOT NULL,device_pin text UNIQUE NOT NULL,user_id text UNIQUE REFERENCES users(id),monthly_salary numeric CHECK(monthly_salary>=0),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE attendance_devices(id text PRIMARY KEY,name text NOT NULL,serial text UNIQUE NOT NULL,secret_hash text NOT NULL,timezone text NOT NULL DEFAULT 'Africa/Cairo',active boolean NOT NULL DEFAULT true,last_seen_at timestamptz,version integer NOT NULL DEFAULT 1,created_at timestamptz DEFAULT now());
CREATE TABLE attendance_policy(id text PRIMARY KEY,data jsonb NOT NULL,version integer NOT NULL DEFAULT 1);
INSERT INTO attendance_policy(id,data) VALUES('default','{"grace_minutes":10,"paid_break_minutes":0,"working_days_per_month":30,"working_hours_per_day":8,"late_multiplier":1,"absence_multiplier":1,"overtime_multiplier":1.5}');
CREATE TABLE attendance_shifts(id text PRIMARY KEY,employee_id text NOT NULL REFERENCES hr_employees(id),shift_date date NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,CHECK(ends_at>starts_at),version integer NOT NULL DEFAULT 1,created_by text REFERENCES users(id),created_at timestamptz DEFAULT now(),UNIQUE(employee_id,starts_at));
CREATE TABLE attendance_punches(id text PRIMARY KEY,employee_id text REFERENCES hr_employees(id),device_id text REFERENCES attendance_devices(id),device_pin text NOT NULL,occurred_at timestamptz NOT NULL,event text NOT NULL CHECK(event IN('in','out','unknown')),source text NOT NULL,reason text,source_key text UNIQUE NOT NULL,created_by text REFERENCES users(id),voided boolean NOT NULL DEFAULT false,void_reason text,voided_by text REFERENCES users(id),version integer NOT NULL DEFAULT 1,created_at timestamptz DEFAULT now(),UNIQUE(device_pin,occurred_at,event));
CREATE TABLE payroll_periods(id text PRIMARY KEY,month text UNIQUE NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved')),stale boolean NOT NULL DEFAULT false,has_late_changes boolean NOT NULL DEFAULT false,calculation jsonb NOT NULL,version integer NOT NULL DEFAULT 1,created_by text REFERENCES users(id),approved_by text REFERENCES users(id),approved_at timestamptz,calculated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz DEFAULT now());
CREATE TABLE attendance_imports(id text PRIMARY KEY,device_id text REFERENCES attendance_devices(id),source text NOT NULL,received_count integer NOT NULL,inserted_count integer NOT NULL,actor_id text REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE INDEX attendance_by_employee_time ON attendance_punches(employee_id,occurred_at);
UPDATE roles SET permissions=permissions || '["attendance.read","attendance.write","attendance.devices","payroll.read","payroll.write","payroll.approve"]'::jsonb WHERE name='manager';
UPDATE roles SET permissions=permissions || '["attendance.read","attendance.write","attendance.devices"]'::jsonb WHERE name='admin';
UPDATE roles SET permissions=permissions || '["attendance.read","payroll.read","payroll.write"]'::jsonb WHERE name='accountant';
UPDATE roles SET permissions=permissions || '["attendance.read","attendance.write"]'::jsonb WHERE name='head_nurse';
UPDATE roles SET permissions=permissions || '["attendance.self"]'::jsonb WHERE name IN('doctor','nurse','reception','lab','stock','quality','maintenance','insurance');
